Body:
> So this introduces a new "protocol" field which seems like it is used to set the npm package.
> 
> But we already have fields to set the npm package any model can have it's own npm package setting regardless of the provider default

Yep. we can use provider.npm instead. I removed `protocol` field.

Here is the example for a model:

```json
"google-vertex": {
	"options": {
		"project": "gcp-project-id",
		"location": "global"
	},
	"models": {
		"zai-org/glm-4.7-maas": {
			"name": "GLM-4.7",
			"provider": { "npm": "@ai-sdk/openai-compatible", "api": "" },
			"limit": { "context": 204800, "output": 131072 },
			"cost": { "input": 0.6, "output": 2.2 },
			"interleaved": {
				"field": "reasoning_content"
			},
			"attachment": false,
			"reasoning": true,
			"family": "glm",
			"temperature": true,
			"tool_call": true,
			"modalities": {
				"input": [ "text" ],
				"output": [ "text" ]
			},
			"release_date": "2025-12-22",
		}
	}
},
```

Did not follow "https://ai-sdk.dev/providers/openai-compatible-providers#provider-specific-options"
```jsonc
  "provider": {
    "newApi": {
      "name": "newApi",
      "npm": "@ai-sdk/openai-compatible",
      "options": {
        "baseURL": "...",
        "apiKey": "..."
      },
      "models": {
        "glm-4.7": {
          "name": "glm-4.7",
          "limit": {
            "context": 204800,
            "output": 131072
          },
          "options": {
            "max_tokens": 131072,
            "enable_thinking": true,
            "thinking": {
              "type": "enabled"
            },
            "reasoningEffort": "high",
            "test": "test-value",
            // expect "test" will forward to request body
            "newApi": {
              "test": "test-value"
            }
          }
        }
      }
    }
  }
```
- 结果
```
{
  "enable_thinking": true,
  "max_tokens": 131072, // ✅
  "messages": [
    {
      "content": "...",
      "role": "system"
    },
    {
      "content": "hello",
      "role": "user"
    }
  ],
  "model": "glm-4.7",
  "reasoning_effort": "high", // ✅
  "stream": true,
  "stream_options": {
    "include_usage": true
  },
  // ✅
  "thinking": {
    "type": "enabled"
  },
  "tool_choice": "auto",
  "tools": [...]
```
I expected "test" to be passed into the request body, but in fact it was ignored.

